def build_page():
    sections_html = []
    for sec in SECTIONS:
        cards = []
        for c in sec["cards"]:
            # Question displayed in both languages but kept in English to reduce translation work
            q_html = html.escape(c["q_en"])
            cards.append(f'''<details class="card"><summary><strong><span class="en">{q_html}</span><span class="gu">{q_html}</span></strong><small><span class="en">{c["marks_en"]}</span><span class="gu">{c["marks_gu"]}</span></small></summary><div class="answer"><div class="en">{c["a_en"]}</div><div class="gu">{c["a_gu"]}</div></div></details>''')
        sections_html.append(f'''<section class="group"><h2>{html.escape(sec["title_en"])}</h2>{''.join(cards)}</section>''')
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DI03000101 · Summer 2026 solved paper</title><style>{CSS}</style></head><body><main class="page"><header class="hero"><div class="eyebrow">Solved question paper · English questions · 80% Gujarati answers</div><div class="lang-switch" aria-label="Choose language"><button type="button" data-lang="en" aria-pressed="true">English</button><button type="button" data-lang="gu" aria-pressed="false">ગુજરાતી</button></div><h1>Electrical Power Transmission & Distribution</h1><div class="meta">GTU Diploma · Electrical Engineering · Semester 3 · Summer 2026 · DI03000101 · 18 May 2026 · 70 marks</div></header>{''.join(sections_html)}<div class="footer">Solved paper for study. Verify clearances/ratings from official standards before field use.</div></main><script>document.querySelectorAll('.lang-switch button').forEach(b=>b.addEventListener('click',()=>{{document.documentElement.lang=b.dataset.lang;document.querySelectorAll('.lang-switch button').forEach(x=>x.setAttribute('aria-pressed',x===b?'true':'false'));}}));</script></body></html>'''
    return page

def main():
    page = build_page()
    out_papers = ROOT / "papers-upload/papers/DI03000101/summer-2026.html"
    out_ws = ROOT / "preview/workshop/DI03000101_summer2026_bilingual.html"
    out_papers.parent.mkdir(parents=True, exist_ok=True)
    out_ws.parent.mkdir(parents=True, exist_ok=True)
    out_papers.write_text(page, encoding="utf-8")
    out_ws.write_text(page, encoding="utf-8")
    d = page.count('<details'); s = page.count('<section'); ce = page.count('class="en"'); cg = page.count('class="gu"')
    # en includes questions (span en) + answer div en; gu includes answer div gu
    print(f"Bilingual: {out_papers} ({len(page)} chars)")
    print(f"details={d}, sections={s}, en={ce}, gu={cg}")

if __name__ == "__main__":
    main()
